import { test, expect } from "./fixtures.js";

test("debug: sample canvas pixels at multiple times", async ({
  page,
  driftServer: server,
}) => {
  await page.goto(`${server.baseURL}/`);
  await page.getByTestId("drift-canvas").waitFor({ state: "visible" });

  const samples: Array<{ t: number; info: unknown }> = [];
  for (const t of [0, 100, 250, 500, 1000, 2000, 3000]) {
    if (t > 0) await page.waitForTimeout(t);
    const info = await page.evaluate(() => {
      const w = globalThis as unknown as {
        __driftEffectRun?: number;
        __driftLastDraw?: { ts: number; stars: number; ctxLost: boolean };
      };
      const c = document.getElementById("drift-canvas") as HTMLCanvasElement | null;
      if (!c) return null;
      const scratch = document.createElement("canvas");
      scratch.width = c.width;
      scratch.height = c.height;
      const ctx2d = scratch.getContext("2d");
      if (!ctx2d) return null;
      ctx2d.drawImage(c, 0, 0);
      const img = ctx2d.getImageData(0, 0, c.width, c.height);
      const p = img.data;
      let sum = 0;
      let sumSq = 0;
      let minL = 999;
      let maxL = 0;
      for (let i = 0; i < p.length; i += 4) {
        const l = 0.299 * p[i] + 0.587 * p[i + 1] + 0.114 * p[i + 2];
        sum += l;
        sumSq += l * l;
        if (l < minL) minL = l;
        if (l > maxL) maxL = l;
      }
      const mean = sum / (p.length / 4);
      return {
        effectRuns: w.__driftEffectRun,
        lastDraw: w.__driftLastDraw,
        mean,
        variance: sumSq / (p.length / 4) - mean * mean,
        minLuma: minL,
        maxLuma: maxL,
      };
    });
    samples.push({ t, info });
  }
  // eslint-disable-next-line no-console
  console.log("[debug-gl11]", JSON.stringify(samples, null, 2));
  expect(samples.length).toBe(7);
});

