import { test, expect } from "./fixtures.js";

test("debug: trace StrictMode + player list", async ({ page, driftServer: server }) => {
  await page.goto(`${server.baseURL}/`);
  await page.getByTestId("drift-canvas").waitFor({ state: "visible" });

  // Watch the player list count over time.
  for (const t of [0, 200, 500, 1000, 2000, 3000, 5000]) {
    if (t > 0) await page.waitForTimeout(t - (t === 200 ? 0 : 0));
    const snapshot = await page.evaluate(() => {
      const w = globalThis as unknown as {
        __driftClient?: {
          currentStatus: string;
          currentCallsign: string | null;
          currentSystemId: string | null;
          presenceStore: { snapshot(): Array<{ callsign: string; isYou: boolean }> };
        };
      };
      const c = w.__driftClient;
      return {
        status: c?.currentStatus ?? null,
        callsign: c?.currentCallsign ?? null,
        systemId: c?.currentSystemId ?? null,
        roster: c?.presenceStore.snapshot().map((p) => ({ callsign: p.callsign, isYou: p.isYou })) ?? null,
        domCount: document.querySelectorAll('[data-testid="drift-player-list-row"]').length,
        domCountText: document.querySelector('[data-testid="drift-player-list-count"]')?.textContent ?? null,
        headerText: document.querySelector('[data-testid="drift-header"]')?.textContent ?? null,
      };
    });
    // eslint-disable-next-line no-console
    console.log(`[t=${t}ms]`, JSON.stringify(snapshot));
  }
  expect(true).toBe(true);
});

